-- scripts/conta/produccion/cuentas/dm1-disparadores-restaurar.sql
--
-- DM1 · PR 2b-1 (01/11) · LO QUE CUENTA LA TANDA (0024), antes y después.
-- SOLO LEE. Las 62 funciones de disparador de las tablas de la foto de Casa
-- Lola: cuántas llevan la guarda y su huella conjunta (el md5 de sus md5, en
-- orden de firma). Y las ventas de antes del corte, de TODAS las cuentas a
-- propósito: aplicar la tanda no mueve ninguna fila.
select clave, valor from (
  select 1 o, '_restaurando_demo existe (antes false, después true)' clave,
    (to_regprocedure('public._restaurando_demo()') is not null)::text valor union all
  select 2, 'las 62 funciones de disparador que llevan la guarda (antes 0, después 62)',
    (select count(*) from unnest(array['public._clock_entry_audit_alta()','public._clock_entry_quien_y_hora()','public._employee_pin_guardar()','public._f01c_receta_puesta()','public._fill_acc_from_assignment()','public._fill_acc_from_employee()','public._fill_acc_from_location()','public._menu_item_price_snapshot()','public._pc01e2_proveedor_iban_cambiado()','public._registro_firma_invalidar()','public._ticket_tras_venta()','public._trg_recipe_item_purchase_format_immutable()','public.company_account_link_sin_dueno()','public.party_al_borrar_proveedor()','public.party_desde_proveedor()','public.party_misma_cuenta()','public.recipe_line_prevent_cycle()','public.set_folvy_code()','public.set_goods_receipt_code()','public.set_inventory_count_code()','public.set_updated_at()','public.supplier_tax_rates_ok()','public.tg_auto_dispatch()','public.tg_auto_print_bag_on_ready()','public.tg_auto_print_on_accept()','public.tg_clock_entry_audit()','public.tg_clock_entry_debounce()','public.tg_clock_entry_orden()','public.tg_count_line_sella_el_motivo()','public.tg_count_line_solo_por_la_puerta()','public.tg_dining_table_same_location()','public.tg_ensure_public_token()','public.tg_goods_receipt_compras_camino()','public.tg_goods_receipt_line_trust()','public.tg_goods_receipt_recompute_average()','public.tg_inventory_count_line_sanity()','public.tg_menu_item_inherit_stock_group()','public.tg_menu_item_override_history()','public.tg_menu_item_override_touch()','public.tg_modifier_option_retiro()','public.tg_notify_on_way_sale()','public.tg_ripf_invalida_revision()','public.tg_sale_close_on_complete()','public.tg_sale_consumption_on_complete()','public.tg_sale_delivery_alarm()','public.tg_sale_entrega_desde_raw()','public.tg_sale_line_consumption()','public.tg_sale_seal_delivered()','public.tg_sale_seal_handed_to_courier()','public.tg_sale_seal_kpi_hitos()','public.tg_sale_service_type_por_interruptor()','public.tg_sale_uber_quien_reparte()','public.tg_sales_hourly_agg_sync()','public.tg_schedule_reject_vacation_conflicts()','public.tg_training_notice_on_assign()','public.trg_article_supplier_recompute_cost()','public.trg_assign_onboarding_training_on_employee_insert()','public.trg_assign_onboarding_training_on_employee_update()','public.trg_propose_vat_on_family()','public.trg_sale_push_status()','public.trg_seal_recipe_version_item()','public.trg_seal_recipe_version_line()']) f
      where pg_get_functiondef(f::regprocedure) like '%if public._restaurando_demo() then return coalesce(new, old); end if;%')::text union all
  select 3, 'huella conjunta de las 62 (antes 585e7aff; después otra; deshecha, 585e7aff)',
    left(md5(string_agg(md5(pg_get_functiondef(f::regprocedure)), '' order by f)), 8)
      from unnest(array['public._clock_entry_audit_alta()','public._clock_entry_quien_y_hora()','public._employee_pin_guardar()','public._f01c_receta_puesta()','public._fill_acc_from_assignment()','public._fill_acc_from_employee()','public._fill_acc_from_location()','public._menu_item_price_snapshot()','public._pc01e2_proveedor_iban_cambiado()','public._registro_firma_invalidar()','public._ticket_tras_venta()','public._trg_recipe_item_purchase_format_immutable()','public.company_account_link_sin_dueno()','public.party_al_borrar_proveedor()','public.party_desde_proveedor()','public.party_misma_cuenta()','public.recipe_line_prevent_cycle()','public.set_folvy_code()','public.set_goods_receipt_code()','public.set_inventory_count_code()','public.set_updated_at()','public.supplier_tax_rates_ok()','public.tg_auto_dispatch()','public.tg_auto_print_bag_on_ready()','public.tg_auto_print_on_accept()','public.tg_clock_entry_audit()','public.tg_clock_entry_debounce()','public.tg_clock_entry_orden()','public.tg_count_line_sella_el_motivo()','public.tg_count_line_solo_por_la_puerta()','public.tg_dining_table_same_location()','public.tg_ensure_public_token()','public.tg_goods_receipt_compras_camino()','public.tg_goods_receipt_line_trust()','public.tg_goods_receipt_recompute_average()','public.tg_inventory_count_line_sanity()','public.tg_menu_item_inherit_stock_group()','public.tg_menu_item_override_history()','public.tg_menu_item_override_touch()','public.tg_modifier_option_retiro()','public.tg_notify_on_way_sale()','public.tg_ripf_invalida_revision()','public.tg_sale_close_on_complete()','public.tg_sale_consumption_on_complete()','public.tg_sale_delivery_alarm()','public.tg_sale_entrega_desde_raw()','public.tg_sale_line_consumption()','public.tg_sale_seal_delivered()','public.tg_sale_seal_handed_to_courier()','public.tg_sale_seal_kpi_hitos()','public.tg_sale_service_type_por_interruptor()','public.tg_sale_uber_quien_reparte()','public.tg_sales_hourly_agg_sync()','public.tg_schedule_reject_vacation_conflicts()','public.tg_training_notice_on_assign()','public.trg_article_supplier_recompute_cost()','public.trg_assign_onboarding_training_on_employee_insert()','public.trg_assign_onboarding_training_on_employee_update()','public.trg_propose_vat_on_family()','public.trg_sale_push_status()','public.trg_seal_recipe_version_item()','public.trg_seal_recipe_version_line()']) f union all
  select 4, 'ventas de antes del 01/11 00:00 UTC (igual antes y después)',
    (select count(*) from public.sale where created_at < timestamptz '2026-11-01 00:00:00+00')::text
) t order by o;
